@media (prefers-color-scheme: dark) {
  :root { --background: #0a0a0a; --foreground: #ededed; }
}

@media (min-width: 1440px) {
  .pixel-product-shell, .pixel-product-header__inner { width: 1440px; max-width: 1440px; }
}

@media (max-width: 900px) {
  .pixel-product-shell, .pixel-product-header__inner { width: min(100% - 48px, 1440px); }
  .pixel-hero { grid-template-columns: 1fr; gap: 28px; }
  .pixel-product-summary { padding-top: 0px; }
  .pixel-product-summary h1 { max-width: 850px; font-size: clamp(48px, 8vw, 72px); }
  .pixel-story-benefits, .pixel-details-gallery { grid-template-columns: 1fr; }
  .pixel-story p { max-width: 850px; }
}

@media (max-width: 600px) {
  .pixel-product-header__inner { width: calc(100% - 32px); height: 62px; }
  .pixel-product-shell { width: calc(100% - 32px); }
  .pixel-logo { letter-spacing: 0.2em; font-size: 15px; }
  .pixel-hero { gap: 25px; padding-top: 22px; padding-bottom: 28px; }
  .pixel-main-image { aspect-ratio: 1 / 0.86; }
  .pixel-thumbnails { gap: 6px; margin-top: 7px; }
  .pixel-product-summary h1 { font-size: clamp(40px, 13vw, 58px); line-height: 0.91; }
  .pixel-brand { margin-bottom: 13px; }
  .pixel-tagline { margin-top: 17px; font-size: 14px; }
  .pixel-subtitle { font-size: 12px; line-height: 1.5; }
  .pixel-price { margin-top: 21px; font-size: 29px; }
  .pixel-shop-button { min-height: 54px; }
  .pixel-story-benefits { gap: 30px; padding-top: 28px; }
  .pixel-benefit-grid { grid-template-columns: 1fr; }
  .pixel-benefit-card { min-height: 105px; }
  .pixel-details-gallery { gap: 31px; padding-top: 22px; }
  .pixel-spec-row { min-height: 39px; }
  .pixel-gallery-grid { grid-template-columns: 1fr 1fr; }
  .pixel-gallery-item:last-child { grid-column: 1 / -1; }
  .pixel-bottom-strip { grid-template-columns: 1fr; gap: 28px; padding-bottom: 34px; }
}

@media (max-width: 390px) {
  .pixel-product-shell, .pixel-product-header__inner { width: calc(100% - 24px); }
  .pixel-product-summary h1 { font-size: 39px; }
  .pixel-benefit-card { grid-template-columns: 31px minmax(0px, 1fr); padding: 13px 10px; }
  .pixel-benefit-icon, .pixel-benefit-icon svg { width: 25px; height: 25px; }
}

@media (min-width: 1441px) {
  .pixel-product-shell, .pixel-product-header__inner { width: 1440px; max-width: 1440px; }
}
